"""Apply the unchanged free-form scoring rule to the external reference."""
import hashlib
import json
import re
import sys
from fractions import Fraction
from pathlib import Path

from audit_d20 import audit_data, score_free


def parse_box(text):
    matches = re.findall(r"\\boxed\s*\{\s*([+-]?[0-9]+(?:,[0-9]{3})*(?:\.[0-9]+)?)\s*\}", text)
    for match in reversed(matches):
        value = Fraction(match.replace(",", ""))
        if value.denominator == 1:
            return value.numerator
    return None


def rescore(rows):
    for row in rows:
        parsed = [parse_box(text) for text in row["text"]]
        yield {**row, "parsed": parsed, "rewards": [int(value == row["gold"]) for value in parsed]}


def main(datafile, output, destination):
    raw = json.loads(output.read_bytes())
    assert raw["mode"] == "free" and set(raw["panels"]) == {"screen", "confirmation"}
    assert raw["model_revision"] == "aafeb0fc6f22cbf0eaeed126eff8be45b0360a35"
    assert raw["panels_sha256"] == hashlib.sha256(datafile.read_bytes()).hexdigest()
    data = json.loads(datafile.read_bytes())["panels"]
    count = audit_data(data)
    scores = {name: score_free(data[name], rows) for name, rows in raw["panels"].items()}
    boxed = {name: score_free(data[name], list(rescore(rows)), parser=parse_box)
             for name, rows in raw["panels"].items()}
    strict_pass = all(row["pass"] for row in scores.values())
    boxed_pass = all(row["pass"] for row in boxed.values())
    record = {"panels": scores, "matched_screen_criterion": strict_pass, "boxed_diagnostic": boxed,
              "boxed_thresholds_met": boxed_pass,
              "parity_reward_mode": "marker" if strict_pass else "box" if boxed_pass else None,
              "model_revision": raw["model_revision"], "identity": raw["checkpoint_sha256"],
              "panel_questions_verified": count, "panels_sha256": raw["panels_sha256"]}
    destination.write_text(json.dumps(record, sort_keys=True, indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main(*(Path(value) for value in sys.argv[1:]))
